\label{def:admissible}
We say that a motif family $\mathcal{M}$ is \emph{$C$-admissible} if \begin{enumerate}
\item \label{cond:connect}For all ${\mathsf{M}}\in \mathcal{M}$, ${\mathsf{M}}$ is connected;
    \item\label{cond:num} There exists $C=o\pth{\frac{\log n}{\max\pth{\log\log n,-\log\rho}}}$ such that $\mathsf{{v}}({\mathsf{M}})\vee\mathsf{{e}}({\mathsf{M}})\le C$ for all ${\mathsf{M}}\in \mathcal{M}$;
    \item\label{cond:signal-strength} $\sum_{{\mathsf{M}}\in \mathcal{M}} \rho^{2\mathsf{{e}}({\mathsf{M}})}\ge 400$;
    \item\label{cond:subgraph} There exists a small constant $\epsilon_0$ such that, $n^{\mathsf{{v}}({\mathsf{M}}')} p^{\mathsf{{e}}({\mathsf{M}}')}\ge n^{\epsilon_0}$ for all ${\mathsf{M}}\in \mathcal{M}$ and subgraph $\emptyset\neq {\mathsf{M}}'\subseteq {\mathsf{M}}$. 
\end{enumerate}

\label{thm:admissible}
    For any \emph{$C$-admissible} motif family $\mathcal{M}$, there exist $\tau,\omega_{\mathsf{M}}\in \mathbb{R}$ such that,
    \begin{align*}
        \mathcal{P}_0\pth{\mathcal{T}_\mathcal{M}\ge\tau}+\mathcal{P}_1(\mathcal{T}_\mathcal{M}< \tau)\le 0.05.
    \end{align*}

\label{prop:TypeI-admissible}
    For the statistic $\mathcal{T}_\mathcal{M}$ with weight $\omega_{\mathsf{M}} = \frac{\rho^{\mathsf{{e}}({\mathsf{M}})} (n-\mathsf{{v}}({\mathsf{M}}))!}{n! (p(1-p))^{\mathsf{{e}}({\mathsf{M}})}\mathsf{aut}({\mathsf{M}})}$, if $\tau = \frac{1}{2}\mathbb{E}_{\mathcal{P}_1}\qth{\mathcal{T}_\mathcal{M}}$, then 
    \begin{align*}
        \mathcal{P}_0\pth{\mathcal{T}_\mathcal{M}\ge \tau}\le \frac{4}{\sum_{{\mathsf{M}}\in \mathcal{M}} \rho^{2\mathsf{{e}}({\mathsf{M}})}}.
    \end{align*}

\label{prop:admissible-TypeII}
    For motif counting statistic $\mathcal{T}_\mathcal{M}$ with \emph{$C$-admissible}  family $\mathcal{M}$ and weight $\omega_{\mathsf{M}} = \frac{\rho^{\mathsf{{e}}({\mathsf{M}})}(n-\mathsf{{v}}({\mathsf{M}}))!}{n!(p(1-p))^{\mathsf{{e}}({\mathsf{M}})}\mathsf{aut}({\mathsf{M}})}$, if $\tau = \frac{1}{2}\mathbb{E}_{\mathcal{P}_1}\qth{\mathcal{T}_\mathcal{M}}$, then \begin{align*}
        \mathcal{P}_1\pth{\mathcal{T}_\mathcal{M}<\tau}\le 4\Bigg(3n^{-\epsilon_0/2}(4C)^{8C}\rho^{-2C}+\frac{\exp\pth{\frac{C^2}{n-2C+1}}+1}{\sum_{{\mathsf{M}}\in \mathcal{M}}\rho^{2\mathsf{{e}}({\mathsf{M}})}}+\exp\pth{\frac{C^2}{n-2C+1}}-1\Bigg).
    \end{align*}

Pick \begin{align*}
    \omega_{\mathsf{M}} = \frac{\rho^{\mathsf{{e}}({\mathsf{M}})}(n-\mathsf{{v}}({\mathsf{M}}))!}{n!(p(1-p))^{\mathsf{{e}}({\mathsf{M}})}\mathsf{aut}({\mathsf{M}})},\quad \tau = \frac{1}{2}\mathbb{E}_{\mathcal{P}_1}\qth{\mathcal{T}_\mathcal{M}} = \frac{1}{2}\sum_{{\mathsf{M}}\in\mathcal{M}} \rho^{2\mathsf{{e}}({\mathsf{M}})}.
\end{align*}
By the Condition~\ref{cond:signal-strength} in Definition~\ref{def:admissible}, we have $\sum_{{\mathsf{M}}\in \mathcal{M}} \rho^{2\mathsf{{e}}({\mathsf{M}})}\ge 400$ for a \emph{$C$-admissible} motif family $\mathcal{M}$.
By Proposition~\ref{prop:TypeI-admissible}, the Type I error is upper bounded by \begin{align}\label{eq:TypeI-error}
    \mathcal{P}_0\pth{\mathcal{T}_\mathcal{M}\ge \tau}\le \frac{4}{\sum_{{\mathsf{M}}\in \mathcal{M}} \rho^{2\mathsf{{e}}({\mathsf{M}})}}\le 0.01.
\end{align}
By Proposition~\ref{prop:admissible-TypeII}, the Type II error is upper bounded by \begin{align}\label{eq:TypeII-error}
    \mathcal{P}_1\pth{\mathcal{T}_\mathcal{M}<\tau}\le 4\Bigg(3n^{-\epsilon_0/2}(4C)^{8C}\rho^{-2C}+\frac{\exp\pth{\frac{C^2}{n-2C+1}}+1}{\sum_{{\mathsf{M}}\in \mathcal{M}}\rho^{2\mathsf{{e}}({\mathsf{M}})}}+\exp\pth{\frac{C^2}{n-2C+1}}-1\Bigg).
\end{align}
For any $C = o\pth{\frac{\log n}{\max\sth{\log\log n,-\log\rho}}}$ and sufficiently large $n$, we have $3n^{-\epsilon_0/2}(4C)^{8C}\rho^{-2C}\le \frac{1}{400}$ and $\exp\pth{\frac{C^2}{n-2C+1}}-1\le \frac{1}{400}$. By~\eqref{eq:TypeII-error}, we obtain \begin{align*}
    \mathcal{P}_1\pth{\mathcal{T}_\mathcal{M}<\tau}&\le 4\pth{\frac{1}{400}+\frac{1+1/400}{\sum_{{\mathsf{M}}\in \mathcal{M}}\rho^{2\mathsf{{e}}({\mathsf{M}})}}+\frac{1}{400}}\\&\le 4\pth{\frac{1}{400}+\frac{2}{400}+\frac{1}{400}}=0.04,
\end{align*}
where the last inequality applies the fact that  $\sum_{{\mathsf{M}}\in \mathcal{M}} \rho^{2\mathsf{{e}}({\mathsf{M}})}\ge 400$ for a \emph{$C$-admissible} motif family $\mathcal{M}$.
Consequently, combining this with~\eqref{eq:TypeI-error}, we obtain 
\begin{equation*}
    \mathcal{P}_0\pth{\mathcal{T}_\mathcal{M}\ge \tau}+\mathcal{P}_1\pth{\mathcal{T}_\mathcal{M}<\tau}\le 0.05.\qedhere
\end{equation*}

\label{lem:motif-family-lwbd}
    For the motif family $ \mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)$  with $d\ge 3$, we have\begin{align}\label{eq:motif-family-lwbd}
        \frac{1}{2}\pth{\frac{2(N_{\mathsf{e}}-d-1)}{ed^{\frac{d}{d-2}}(d-1)}}^{\frac{d-2}{d}(N_{\mathsf{e}}-d-1)}\le |\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)|\le \pth{\frac{2(N_{\mathsf{e}}-d-1)}{d(d-1)}}^{\frac{d-2}{d}(N_{\mathsf{e}}-d-1)}.
    \end{align}

\label{lem:subgraph}
    For any motif ${\mathsf{M}}\in \mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)$ and subgraph $\emptyset\neq {\mathsf{M}}'\subseteq {\mathsf{M}}$, we have 
    \begin{align*}
        d\,\mathsf{{v}}({\mathsf{M}}')\ge 2\,\mathsf{{e}}({\mathsf{M}}')+1.
    \end{align*}

\label{thm:bd-degree-motif-main}
     If $p=n^{-a}$ with $0<a\le \frac{2}{3}$ and  $d=\qth{\frac{2}{a}}$, when $N_{\mathsf{e}}=o\pth{\frac{\log n}{\max\pth{\log\log n,-\log\rho}}}$ and $N_{\mathsf{e}}\ge \frac{C_1(d)}{\rho^{2d/(d-2)}}$ for some constant $C_1(d)$ depending on $d$,\begin{align*}
        \mathcal{P}_0\pth{\mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}\ge \tau}+\mathcal{P}_1\pth{\mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}<\tau}\le 0.05.
    \end{align*}

    If $p=n^{-o(1)}$, then for any constant $\epsilon>0$, when $N_{\mathsf{e}} = o\pth{\frac{\log n}{\max\pth{\log\log n,-\log\rho}}}$ and $N_{\mathsf{e}}\ge \frac{C_2(\epsilon)}{\rho^{2+\epsilon}}$ for some constant $C_2(\epsilon)$ depending on $\epsilon$,\begin{align*}
        \mathcal{P}_0\pth{\mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}\ge \tau}+\mathcal{P}_1\pth{\mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}<\tau}\le 0.05.
    \end{align*}

    Furthermore, $\mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}$ is  computable in $O(n^{N_{\mathsf{e}}})$.

We first show that $\mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}$ is computable in time $O(n^{N_{\mathsf{e}}})$. For any ${\mathsf{M}}\in \mathcal{M}$, since there are $\binom{n}{\mathsf{{v}}({\mathsf{M}})}(\mathsf{{v}}({\mathsf{M}})!)$ injections from $V({\mathsf{M}})$ to $V(\bar{G}_1)$,
the injective homomorphism number $\mathsf{inj}({\mathsf{M}},\bar{G}_1)$ takes $\binom{n}{\mathsf{{v}}({\mathsf{M}})}(\mathsf{{v}}({\mathsf{M}})!)\le n^{\mathsf{{v}}({\mathsf{M}})}$ time for computation. Similarly, the injective homomorphism number $\mathsf{inj}({\mathsf{M}},\bar{G}_2)$ can be computed in time $n^{\mathsf{{v}}({\mathsf{M}})}$. Consequently, the time complexity for ${\mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}}$ is bounded by $2n^{\mathsf{{v}}({\mathsf{M}})} |{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}|$, and we have \begin{align*}
    2n^{\mathsf{{v}}({\mathsf{M}})} |{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}|&\overset{\mathrm{(a)}}{\le} 2n^{\ell(d-1)+4} \pth{\frac{2(N_{\mathsf{e}}-d-1)}{d(d-1)}}^{\frac{d-2}{d}\cdot (N_{\mathsf{e}}-d-1)}\\&\overset{\mathrm{(b)}}{\le} 2n^{2(N_{\mathsf{e}}+d-1)/d}(N_{\mathsf{e}})^{N_{\mathsf{e}}}\overset{\mathrm{(c)}}{\le} n^{N_{\mathsf{e}}},
\end{align*}
where $\mathrm{(a)}$ is due to $\mathsf{{v}}({\mathsf{M}})=\ell(d-1)+4$ and~\eqref{eq:motif-family-lwbd} in Lemma~\ref{lem:motif-family-lwbd}; $\mathrm{(b)}$ is because $\ell(d-1)+4 = \frac{2(N_{\mathsf{e}}+d-1)}{d}$, $\frac{2(N_{\mathsf{e}}-d-1)}{d(d-1)}\le N_{\mathsf{e}}$, and $\frac{d-2}{d}\cdot (N_{\mathsf{e}}-d-1)\le N_{\mathsf{e}}$; $\mathrm{(c)}$ is because $N_{\mathsf{e}} = o(\frac{\log n}{\log \log n})$ implies $2(N_{\mathsf{e}})^{N_{\mathsf{e}}} = n^{o(1)}$ and $\frac{2(N_{\mathsf{e}}+d-1)}{d}\le \frac{2N_{\mathsf{e}}}{3}+2<N_{\mathsf{e}}$.

We then show the theoretical guarantee on $\mathcal{P}_0\pth{\mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}\ge \tau}+\mathcal{P}_1\pth{\mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}< \tau}$. By Theorem~\ref{thm:admissible}, it suffices to show that $\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)$ is \emph{$C$-admissible}. Since $N_{\mathsf{v}}\le N_{\mathsf{e}}$ and $N_{\mathsf{e}} = o\pth{\frac{\log n}{\max \pth{\log \log n, -\log \rho}}}$, taking $C = N_{\mathsf{e}}$ yields Condition~\ref{cond:num}. By Lemma~\ref{lem:subgraph}, for all ${\mathsf{M}}\in \mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)$ and ${\mathsf{M}}'\subseteq {\mathsf{M}}$, we have \begin{align*}
    n^{\mathsf{{v}}({\mathsf{M}}')}p^{\mathsf{{e}}({\mathsf{M}}')}\ge n^{(2\mathsf{{e}}({\mathsf{M}}')+1)/d}p^{\mathsf{{e}}({\mathsf{M}}')}\ge n^{1/d},
\end{align*}
where the last inequality is because $np^{d/2}\ge 1$ by the choice of $d$. Pick $\epsilon_0 = 1/d$, we conclude the Condition~\ref{cond:subgraph} in Definition~\ref{def:admissible}. Since all ${\mathsf{M}}\in \mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)$ are connected, it remains to verify the Condition~\ref{cond:signal-strength} $\sum_{{\mathsf{M}}\in \mathcal{M}}\rho^{2\mathsf{{e}}({\mathsf{M}})}\ge 400$.

We first focus on the case $p = n^{-a}$ with $0<a\le \frac{2}{3}$. By Lemma~\ref{lem:motif-family-lwbd}, \begin{align*}
    \sum_{{\mathsf{M}}\in \mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}\rho^{2\mathsf{{e}}({\mathsf{M}})}\ge \frac{1}{2}\pth{\frac{2(N_{\mathsf{e}}-d-1)}{ed^{\frac{d}{d-2}}(d-1)}}^{\frac{d-2}{d}(N_{\mathsf{e}}-d-1)}\rho^{2d+2}.
\end{align*}
We first prove that there exists a constant $C(d)$ depending on $d$ such that \begin{align*}
    \frac{1}{2}(C(d))^{\frac{d-2}{d}\rho^{-2d/(d-2)}}\rho^{2d+2}\ge 400
\end{align*}
for any $0\le \rho\le 1$ and integer $d\ge 3$.
Pick $C(d) = \exp\pth{3\log 800+\frac{d(2d+2)}{d-2}}$. Then, \begin{align*}
    &~\frac{d-2}{d}\rho^{-\frac{2d}{d-2}}\log (C(d))+(2d+2)\log\rho \\=&~ \frac{d-2}{d}\rho^{-\frac{2d}{d-2}}\pth{3\log 800+\frac{d(2d+2)}{d-2}}+(2d+2)\log\rho\\\overset{\mathrm{(a)}}{\ge}&~ \frac{3(d-2)\log(800)}{d}+(2d+2)\pth{\frac{1}{\rho^2}+\log \rho}\overset{\mathrm{(b)}}{\ge}   \log 800,
\end{align*}
where $\mathrm{(a)}$ is because $\rho\le 1$ and $\frac{2d}{d-2}\ge 2$; $\mathrm{(b)}$ follows from $\log x+\frac{1}{x^2}\ge 0$ for any $x>0$ and $\frac{3(d-2)}{d}\ge 1$ for any $d\ge 3$. Therefore, we obtain $\frac{1}{2}(C(d))^{\frac{d-2}{d}\rho^{-2d/(d-2)}} \rho^{2d+2}\ge 400$. Let $C_1(d)\triangleq d+1+\frac{1}{2}e d^{d/(d-2)} (d-1) C(d)$. When $N_{\mathsf{e}}\ge \frac{C_1(d)}{\rho^{2d/(d-2)}}$, we have \begin{align*}
    \frac{2(N_{\mathsf{e}}-d-1)\rho^{2d/(d-2)}}{ed^{d/(d-2)}(d-1)} &\ge \frac{2C_1(d) - 2(d+1) \rho^{2d/(d-2)}}{ed^{d/(d-2)}(d-1)} \ge \frac{2C_1(d) - 2(d+1)}{ed^{d/(d-2)}(d-1)} = C(d)
\end{align*}
and \begin{align*}
    \frac{d-2}{d}\cdot (N_{\mathsf{e}}-d-1) \ge \frac{d-2}{d}\cdot\pth{\frac{d+1}{\rho^{2d/(d-2)}}-d-1} \ge \frac{d-2}{d} \rho^{-\frac{2d}{d-2}}.
\end{align*}
Therefore, \begin{align*}
    \sum_{{\mathsf{M}}\in \mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}\rho^{2\mathsf{{e}}({\mathsf{M}})} &\ge \frac{1}{2} \pth{\frac{2(N_{\mathsf{e}}-d-1)\rho^{2d/(d-2)}}{ed^{d/(d-2)}(d-1)}}^{\frac{d-2}{d}\cdot (N_{\mathsf{e}}-d-1)}\rho^{2d+2}\\&\ge \frac{1}{2}(C(d))^{\frac{d-2}{d}\rho^{-2d/(d-2)}} \rho^{2d+2}\ge 400.
\end{align*} 

We then focus on the case $p = n^{o(1)}$. For any $\epsilon>0$, pick $d = \qth{\frac{4}{\epsilon}}+3$. Then $\frac{2d}{d-2}<2+\epsilon$. Let $C_2(\epsilon)\triangleq C_1\pth{\qth{\frac{4}{\epsilon}}+3}$. We have shown that when $N_{\mathsf{e}}\ge \frac{C_1(d)}{\rho^{2d/(d-2)}}$, we have $\sum_{{\mathsf{M}}\in \mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}\rho^{2\mathsf{{e}}({\mathsf{M}})}\ge 400$.
Since $\frac{C_1(d)}{\rho^{2d/(d-2)}} \le \frac{C_2(\epsilon)}{\rho^{2+\epsilon}}$, we also have $\sum_{{\mathsf{M}}\in \mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}\rho^{2\mathsf{{e}}({\mathsf{M}})}\ge 400$.
Consequently, $\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)$ is \emph{$N_{\mathsf{e}}$-admissible}. By Theorem~\ref{thm:admissible}, we obtain that \begin{equation*}
\mathcal{P}_0\pth{\mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}\ge \tau}+\mathcal{P}_1\pth{\mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}< \tau}\le 0.05.\qedhere
\end{equation*}

\label{thm:bd-degree-motif-general}
      If $p=n^{-a}$ with constant $0<a< \frac{2}{3}$, then for $d=3\cdot \indc{\frac{2}{5}<a<\frac{2}{3}}+\pth{\qth{\frac{2}{a}}-1}\cdot \indc{0<a\le \frac{2}{5}}$, when $N_{\mathsf{e}}=o\pth{\frac{\log n}{\max\pth{\log\log n,-\log\rho}}}$ and $N_{\mathsf{e}}\ge \frac{C_1(d)}{\rho^{2d/(d-2)}}$ for some constant $C_1(d)$ depending on $d$,\begin{align*}
        \mathcal{P}_0\pth{\mathcal{T}_{\mathcal{M}(N_{\mathsf{e}},d)}\ge \tau}+\mathcal{P}_1\pth{\mathcal{T}_{\mathcal{M}(N_{\mathsf{e}},d)}<\tau}\le 0.05.
    \end{align*}

    If $p=n^{-o(1)}$, then for any constant $\epsilon>0$, when $N_{\mathsf{e}} = o\pth{\frac{\log n}{\max\pth{\log\log n,-\log\rho}}}$ and $N_{\mathsf{e}}\ge \frac{C_2(\epsilon)}{\rho^{2+\epsilon}}$ for some constant $C_2(\epsilon)$ depending on $\epsilon$,\begin{align*}
        \mathcal{P}_0\pth{\mathcal{T}_{\mathcal{M}(N_{\mathsf{e}},d)}\ge \tau}+\mathcal{P}_1\pth{\mathcal{T}_{\mathcal{M}(N_{\mathsf{e}},d)}<\tau}\le 0.05.
    \end{align*}

    Furthermore, $\mathcal{T}_{\mathcal{M}(N_{\mathsf{e}},d)}$ is  computable in time $O(n^{N_{\mathsf{e}}+1+o(1)})$.

We first show that the statistic $\mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}$ is computable in time $O(n^{N_{\mathsf{e}}+1+o(1)})$. Recall that the injective homomorphism number $\mathsf{inj}({\mathsf{M}},\bar{G}_1),\mathsf{inj}({\mathsf{M}},\bar{G}_2)$ can be computed in time $2n^{\mathsf{{v}}({\mathsf{M}})}$. Since for connected  motif ${\mathsf{M}}$ with $N_{\mathsf{e}}$ edges, the number of vertices is bounded by $N_{\mathsf{e}}+1$, the total computation time is then bounded by $2n^{N_{\mathsf{e}}+1}|\mathcal{M}(N_{\mathsf{e}},d)|$. We then upper bound $|\mathcal{M}(N_{\mathsf{e}},d)|$. We note that \begin{align*}
    |\mathcal{M}(N_{\mathsf{e}},d)|
\le \sum_{N_{\mathsf{v}}=1}^{N_{\mathsf{e}}+1}\binom{\binom{N_{\mathsf{v}}}{2}}{N_{\mathsf{e}}}
\le (N_{\mathsf{e}}+1)\binom{\binom{N_{\mathsf{e}}+1}{2}}{N_{\mathsf{e}}}
\le (N_{\mathsf{e}}+1)\pth{\frac{e(N_{\mathsf{e}}+1)}{2}}^{N_{\mathsf{e}}},
\end{align*}
where the first inequality is because $1\le N_{\mathsf{v}}\le N_{\mathsf{e}}+1$ and there are at most $\binom{N_{\mathsf{v}}}{2}$ edges with $N_{\mathsf{v}}$ vertices; the last inequality is because $\binom{m_1}{m_2}\le\pth{\frac{em_1}{m_2}}^{m_2}$ for all $m_1,m_2\in \mathbb{N}$. Since $N_e = o\pth{\frac{\log n}{\log \log n}}$, we have $(N_{\mathsf{e}}+1)\pth{\frac{e(N_{\mathsf{e}}+1)}{2}}^{N_{\mathsf{e}}} = n^{o(1)}$. Consequently, the overall computation time is $n^{N_{\mathsf{e}}+1+o(1)}$.


We then show the theoretical guarantee. We prove that $\mathcal{M}(N_{\mathsf{e}},d)$ is \emph{$(N_{\mathsf{e}}{+}1)$-admissible}.
For Condition~\ref{cond:num}, since there are at most $N_{\mathsf{e}}+1$ vertices in a connected motif with $N_{\mathsf{e}}$ edges, choosing $C = N_{\mathsf{e}} +1$ satisfies the Condition~\ref{cond:num}. Since $\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)\subseteq \mathcal{M}(N_{\mathsf{e}},d)$ and $\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)$ is \emph{$N_{\mathsf{e}}$-admissible}, we have \begin{align*}
    \sum_{{\mathsf{M}}\in \mathcal{M}(N_{\mathsf{e}},d)}\rho^{2\mathsf{{e}}({\mathsf{M}})}\ge  \sum_{{\mathsf{M}}\in \mathcal{M}(N_{\mathsf{v}}, N_{\mathsf{e}},d)}\rho^{2\mathsf{{e}}({\mathsf{M}})}\ge 400.
\end{align*}
For Condition~\ref{cond:subgraph}, since the maximum degree of all ${\mathsf{M}}\in\mathcal{M}$ is bounded by $d$, we have $\mathsf{{e}}({\mathsf{M}}')\le \frac{d}{2}\mathsf{{v}}({\mathsf{M}}')$ for all ${\mathsf{M}}'\subseteq {\mathsf{M}}$. When $p=n^{o(1)}$, we have $n^{\mathsf{{v}}({\mathsf{M}}')}p^{\mathsf{{e}}({\mathsf{M}}')}\ge n^{1/2}$.
When $p = n^{-a}$ with constant $0<a\le \frac{2}{5}$, we pick $d = \qth{\frac{2}{a}}-1$. Since $d\le \frac{2}{a}-1$,  we have \begin{align*}
    n^{\mathsf{{v}}({\mathsf{M}}')}p^{\mathsf{{e}}({\mathsf{M}}')}&\ge n^{\mathsf{{v}}({\mathsf{M}}')}p^{d\mathsf{{v}}({\mathsf{M}}')/2}\ge (np^{(2/a-1)/2})^{\mathsf{{v}}({\mathsf{M}}')}\\&=(n^{a/2})^{\mathsf{{v}}({\mathsf{M}}')}\ge n^{a/2}.
\end{align*}
When $p=n^{-a}$ with constant $\frac{2}{5}<a<\frac{2}{3}$, we pick $d=3$.
Consequently, 
\begin{align*}
    n^{\mathsf{{v}}({\mathsf{M}}')}p^{\mathsf{{e}}({\mathsf{M}}')}&\ge n^{\mathsf{{v}}({\mathsf{M}}')}p^{d\mathsf{{v}}({\mathsf{M}}')/2}\\&=(n^{1-3a/2})^{\mathsf{{v}}({\mathsf{M}}')}\ge n^{1-3a/2}.
\end{align*}
Picking $\epsilon_0 = \min\pth{\frac{a}{2},1-\frac{3a}{2}}$ yields the Condition~\ref{cond:subgraph} in Definition~\ref{def:admissible}. Since all ${\mathsf{M}}\in \mathcal{M}(N_{\mathsf{e}},d)$ are connected, we conclude that $\mathcal{M}(N_{\mathsf{e}},d)$ is \emph{$C$-admissible}. By Theorem~\ref{thm:admissible}, we have \begin{equation*}
    \mathcal{P}_0(\mathcal{T}_{\mathcal{M}(N_{\mathsf{e}},d)}\ge\tau)+\mathcal{P}_1(\mathcal{T}_{\mathcal{M}(N_{\mathsf{e}},d)}<\tau)\le 0.05.\qedhere
\end{equation*}

It is then natural to ask:
\begin{center}
\emph{Can we design a finer motif family so that motif counting succeeds when $p\ge n^{-1+\delta}$?}
\end{center}

We separate it into two cases.

\textbf{Case 1: ${\mathsf{M}}'$ is a tree.} We note that for any tree ${\mathsf{M}}'$, we have $\mathsf{{e}}({\mathsf{M}}') = \mathsf{{v}}({\mathsf{M}}')-1$, and thus $\mathsf{{e}}({\mathsf{M}}')/\mathsf{{v}}({\mathsf{M}}')<1<1+\delta$.

\textbf{Case 2: ${\mathsf{M}}'$ contains at least one cycle.}
If ${\mathsf{M}}'$ is disconnected, we may ignore all tree components since they satisfy $\mathsf{{e}}/\mathsf{{v}}<1$ and can only decrease the ratio $\mathsf{{e}}({\mathsf{M}}')/\mathsf{{v}}({\mathsf{M}}')$.
Therefore, it suffices to consider the connected component of ${\mathsf{M}}'$ that contains a cycle, and we may assume without loss of generality that ${\mathsf{M}}'$ is connected and contains a cycle.  

Let $\mathcal{V}\triangleq \sth{v_{i,j}:1\le i\le \ell,1\le j\le 4}$.
By construction, any two  vertices in $\mathcal{V}$ are well separated: along any path connecting them, there are at least $t-1$ intermediate vertices (equivalently, their graph distance is at least $t$). Consequently, any cycle must contain at least 3 vertices in $\mathcal{V}$, and the segments between consecutive such vertices contribute at least $t$ vertices each, so the shortest possible cycle has length at least $3t$, and thus $\mathsf{{v}}({\mathsf{M}}')\ge 3t$. Moreover, in any subgraph ${\mathsf{M}}'\subseteq {\mathsf{M}}$, each degree-$3$ vertex requires at least $t$ vertices (itself plus at least $t-1$ separating vertices), hence the number of degree-$3$ vertices in ${\mathsf{M}}'$ is at most $\lfloor \mathsf{{v}}({\mathsf{M}}')/t\rfloor+1$. Since $2\mathsf{{e}}({\mathsf{M}}') = \sum_{v\in V({\mathsf{M}}')}\operatorname{deg}(v)$, where $\operatorname{deg}(v)$ denotes the degree of vertex $v$, we then have \begin{align*}
    2\mathsf{{e}}({\mathsf{M}}') = \sum_{v\in V({\mathsf{M}}')}\operatorname{deg}(v)\le  \sum_{v\in V({\mathsf{M}}')}(2+\indc{\operatorname{deg}(v)=3})\le 2\mathsf{{v}}({\mathsf{M}}')+\mathsf{{v}}({\mathsf{M}}')/t+1, 
\end{align*}
where the last inequality uses $\sum_{v\in V({\mathsf{M}}')}\indc{\operatorname{deg}(v)=3}\le \lfloor \mathsf{{v}}({\mathsf{M}}')/t\rfloor+1\le  \mathsf{{v}}({\mathsf{M}}')/t+1$. Since $\mathsf{{v}}({\mathsf{M}}')\ge 3t$, we then obtain \begin{align*}
    \frac{\mathsf{{e}}({\mathsf{M}}')}{\mathsf{{v}}({\mathsf{M}}')}\le 1+\frac{1}{2t}+\frac{1}{2\mathsf{{v}}({\mathsf{M}}')}\le 1+\frac{1}{2t}+\frac{1}{6t} = 1+\frac{2}{3t}\le 1+\delta,
\end{align*}
where the last inequality is because $t = \lfloor \delta^{-1}\rfloor+1\ge \delta^{-1}$.

\label{thm:refined-main-thm}
    Assume that $p\ge n^{-1+\delta}$ with some constant $\delta>0$. When $N_{\mathsf{e}} = o\pth{\frac{\log n}{\max(\log\log n,-\log \rho)}}$ and $N_{\mathsf{e}} \ge \frac{C(\delta)}{\rho^{24/\delta}}$ for a constant $C(\delta)$, then there exists a threshold $\tau$ such that 
    \begin{align*}
        \mathcal{P}_0(\mathcal{T}_{\overline{\mathcal{M}}(N_{\mathsf{v}},N_{\mathsf{e}},3)}\ge \tau)+\mathcal{P}_1(\mathcal{T}_{\overline{\mathcal{M}}(N_{\mathsf{v}},N_{\mathsf{e}},3)}< \tau)\le 0.05.
    \end{align*}

By Theorem~\ref{thm:admissible}, it suffices to show that $\overline{\mathcal{M}}(N_{\mathsf{v}},N_{\mathsf{e}},3)$ is \emph{$C-$admissible}. Conditions~\ref{cond:connect} and~\ref{cond:num} follow from the construction of $\overline{\mathcal{M}}(N_{\mathsf{v}},N_{\mathsf{e}},3)$ and $N_{\mathsf{v}}\le N_{\mathsf{e}} =o\pth{\frac{\log n}{\max(\log\log n,-\log \rho)}}$.
By Lemma~\ref{lem:refined-aut-lwbd}, for all ${\mathsf{M}}\in \mathcal{M}$ and $\emptyset\neq {\mathsf{M}}'\subseteq {\mathsf{M}}$, we have \begin{align*}
    n^{\mathsf{{v}}({\mathsf{M}}')}p^{\mathsf{{e}}({\mathsf{M}}')}\ge n^{\mathsf{{v}}({\mathsf{M}}')}p^{(1+\delta)\mathsf{{v}}({\mathsf{M}}')}\ge n^{\mathsf{{v}}({\mathsf{M}}')\delta^2}\ge n^{\delta^2}.
\end{align*}
Taking $\epsilon_0 = \delta^2$ yields Condition~\ref{cond:subgraph}. It remains to verify Condition~\ref{cond:signal-strength}. Recall that $N_{\mathsf{e}} = t(6\ell-1)+2$ and $t = \lfloor \delta^{-1}\rfloor+1$. Thus $\ell\ge \frac{N_{\mathsf{e}}}{6t}\ge \frac{\delta N_{\mathsf{e}}}{12}$. By~\eqref{eq:refined-construct},\begin{align*}
    \sum_{{\mathsf{M}}\in \overline{\mathcal{M}}(N_{\mathsf{v}},N_{\mathsf{e}},3)} \rho^{2\mathsf{{e}}({\mathsf{M}})}\ge |\overline{\mathcal{M}}(N_{\mathsf{v}},N_{\mathsf{e}},3)|\rho^{2N_{\mathsf{e}}}\ge \frac{1}{2}\pth{\frac{\delta N_{\mathsf{e}}}{96 e}}^{\delta N_{\mathsf{e}} /12}\rho^{2N_{\mathsf{e}}} = \frac{1}{2}\Big[\Big(\frac{\delta N_{\mathsf{e}}}{96e}\Big)^{\delta /12}\rho^2\Big]^{N_{\mathsf{e}}}.
\end{align*}
Consequently, when $N_{\mathsf{e}}\ge (800/\rho^2)^{12/\delta}\cdot 96e/\delta$, we have $\sum_{{\mathsf{M}}\in \overline{\mathcal{M}}(N_{\mathsf{v}},N_{\mathsf{e}},3)} \rho^{2\mathsf{{e}}({\mathsf{M}})}\ge 400$, which yields Condition~\ref{cond:signal-strength}. We then prove the theorem.

