    |V({\mathsf{H}}_1\triangle {\mathsf{H}}_2)\cap (V({\mathsf{H}}_1)\cap V({\mathsf{H}}_2))| - |V({\mathsf{H}}_1\triangle {\mathsf{H}}_2)\cap V({\mathsf{H}}_0)|\ge 0.
\end{align*}
It remains to prove~\eqref{eq:aux-1} when ${\mathsf{H}}_0 = \emptyset$ and ${\mathsf{H}}_1\neq {\mathsf{H}}_2$. We note that $|V({\mathsf{H}}_1\triangle {\mathsf{H}}_2)\cap V({\mathsf{H}}_0)| = 0$ when ${\mathsf{H}}_0 =\emptyset$.
It suffices to show $|V({\mathsf{H}}_1\triangle {\mathsf{H}}_2)\cap (V({\mathsf{H}}_1)\cap V({\mathsf{H}}_2))|\ge 1$ when ${\mathsf{H}}_1\neq {\mathsf{H}}_2$.
If ${\mathsf{H}}_1\cap {\mathsf{H}}_2=\emptyset$, then ${\mathsf{H}}_1\triangle {\mathsf{H}}_2 = {\mathsf{H}}_1\cup {\mathsf{H}}_2$, and thus \begin{align*}
    |V({\mathsf{H}}_1\triangle {\mathsf{H}}_2)\cap (V({\mathsf{H}}_1)\cap V({\mathsf{H}}_2))| &= |V({\mathsf{H}}_1\cup  {\mathsf{H}}_2)\cap (V({\mathsf{H}}_1)\cap V({\mathsf{H}}_2))|\\&=|V({\mathsf{H}}_1)\cap V({\mathsf{H}}_2)|\ge 1.
\end{align*}
If ${\mathsf{H}}_1\cap {\mathsf{H}}_2\neq \emptyset$, then $V({\mathsf{H}}_1\cap {\mathsf{H}}_2)\neq \emptyset$. Since $|V({\mathsf{H}}_1)\cap V({\mathsf{H}}_2)|\ge 1$, ${\mathsf{H}}_1\cup {\mathsf{H}}_2$ are connected. Recall that ${\mathsf{H}}_1\neq {\mathsf{H}}_2$, and thus $V({\mathsf{H}}_1\triangle {\mathsf{H}}_2)\neq \emptyset$. Therefore,\begin{align*}
    |V({\mathsf{H}}_1\triangle {\mathsf{H}}_2)\cap (V({\mathsf{H}}_1)\cap V({\mathsf{H}}_2))|\ge |V({\mathsf{H}}_1\triangle {\mathsf{H}}_2) \cap V({\mathsf{H}}_1\cap {\mathsf{H}}_2)|\ge 1,
\end{align*}
where the last inequality follows from the fact that ${\mathsf{H}}_1\cup {\mathsf{H}}_2 = ({\mathsf{H}}_1\triangle {\mathsf{H}}_2)\cup ({\mathsf{H}}_1\cap {\mathsf{H}}_2)$ is connected and $V({\mathsf{H}}_1\triangle {\mathsf{H}}_2),V({\mathsf{H}}_1\cap {\mathsf{H}}_2)\neq \emptyset$.
